    txt(m + ' of 2', { style: 'Label/Small', color: 'color/text/secondary', parent: c, name: 'Count', w: 52, align: 'CENTER' });
    iconBtn(c, 'chevron-up', { name: 'Previous match' }); iconBtn(c, 'chevron-down', { name: 'Next match' });
