    al(c, { gap: 12, pad: [0, 16, 0, 20], w: 1440, h: 56, cross: 'center', fill: 'color/bg/brand' });
    const logo = CMP['Logo/Product Lockup'].createInstance(); logo.name = 'Logo'; c.appendChild(logo);
