  const hb = inst('Badge', { Tone: 'Neutral' }, hd, { name: 'Help style' }); setText(hb, 'Label', 'Hints first');
  iconBtn(hd, 'x', { name: 'Close assistant' });
  CMP['Cog Header'] = hd; parent.appendChild(hd);

  // Offline notice
